local UINightCatInstanceBuffDisplayDialog = Class("UINightCatInstanceBuffDisplayDialog")

function UINightCatInstanceBuffDisplayDialog:__init() 
    self._activityId = 0    
    self._allBuffId = {}          --所有的buff    
    self._curEquipBuffIds = {}          --当前装备的buff    

    self._curAllBuffSelectIndex = 0
    self._curBuffSelectIndex = 0
end

function UINightCatInstanceBuffDisplayDialog:__delete()
    self._activityId = 0        
    self._allBuffId = {}          --所有的buff    
    self._curEquipBuffIds = {}          --当前装备的buff    

    self._curAllBuffSelectIndex = 0
end

function UINightCatInstanceBuffDisplayDialog:OnFocus(focus)
    if focus then
        local vo = QuestConfMgr:GetInstance():GetNightCatActivityVo(self._activityId)
        if vo then
            CfUtils.RefreshTopGoods(CfUtils.Split(vo.token))
        end
    end 
end

function UINightCatInstanceBuffDisplayDialog:Awake()
    local argument = self.controller.Argument.parameters
    if argument then
        self._activityId = checkNumber(argument.activityId)  
    end

    if checkNumber(self._activityId) == 0 then
        return
    end

    self:InitData()
    self:FillSelf()
end

function UINightCatInstanceBuffDisplayDialog:InitData()
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2730, self._activityId)
    self._allBuffId = t

    self._curEquipBuffIds = comp:GetEquipBuffInfo()

    local maxNum = QuestConfMgr:GetInstance():GetNightCatMaxEquipBuffNum()
    if table.count(self._curEquipBuffIds) < maxNum then
        for i = table.count(self._curEquipBuffIds) + 1, maxNum do
            table.insert(self._curEquipBuffIds, 0)
        end 
    end
end

function UINightCatInstanceBuffDisplayDialog:FillSelf()
    self:FillAllBuff()
    self:FillCurBuff()
end

function UINightCatInstanceBuffDisplayDialog:FillAllBuff()
    if self._isInitAllBuffList then
        self.AllBuffList:SetListItemCount(table.count(self._allBuffId))
    else
        self._isInitAllBuffList = true
        self.AllBuffList:InitListView(table.count(self._allBuffId), Bind(self, self.OnGetItemByIndex), nil, Bind(self, self.OnGetListItemByIndex))
    end
end

--当前装备的
function UINightCatInstanceBuffDisplayDialog:FillCurBuff()
    if self._isInitCurrentBuffList then
        GameUtils.ReloadData(self.CurrentBuffList, table.count(self._curEquipBuffIds), true)
    else
        self._isInitCurrentBuffList = true
        self.CurrentBuffList:InitGridView(table.count(self._curEquipBuffIds), Bind(self, self.OnRefreshItemsIndex))
    end
end

--当前装备的
function UINightCatInstanceBuffDisplayDialog:OnRefreshItemsIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local luaIndex = index + 1
    local cell = listView:NewListViewItem("Cell")

    local id = self._curEquipBuffIds[luaIndex]
    self:FillBuffItem(cell.gameObject, id)

    --if checkNumber(self._targetBuffId) > 0 and checkNumber(self._targetBuffId) == checkNumber(id) then 
    --    self._targetBuffId = 0
    --    print(self._targetBuffId)
    --    print("11111")
    --    print(cell.gameObject)
    --    CfUtils.PlayAnimation(cell.gameObject, "NightCatInstanceBuffDisplayDialogBubbleAssembly")
    --end

    SetButtonAction(cell.gameObject.transform:Find("BtnNode"), Bind(self, self.OnBtnSelectEquip, luaIndex, id))

    return cell
end

---所有的
function UINightCatInstanceBuffDisplayDialog:OnGetItemByIndex(go, index, row, column)
    if index < 0 then
        return
    end
    local id = self._allBuffId[index + 1]
    self:FillBuffItem(go, id, true)

    SetButtonAction(go.transform:Find("BtnNode"), Bind(self, self.OnBtnSelectAll, index, id))
end

function UINightCatInstanceBuffDisplayDialog:FillBuffItem(go, buffId)
    if not go then
        return
    end
    local btnNodeGo = go.transform:Find("BtnNode")

    local vo = QuestConfMgr:GetInstance():GetNightCatGoodsVo(buffId)
    if not vo then
        CfUtils.SetActive(btnNodeGo.transform:Find("StatusNotGet"), false)
        CfUtils.SetActive(btnNodeGo.transform:Find("StatusHasGet"), false)
        CfUtils.SetUISwitchImage(btnNodeGo.transform:Find("StatusNotSelect/ImgNotSelect"), 1)
        return
    end

    local isUnlock = QuestConfMgr:GetInstance():IsUnlockNightCatBuff(buffId)
    local isEquip = comp:IsEquipBuff(buffId)

    CfUtils.SetActive(btnNodeGo.transform:Find("StatusNotGet"), not isUnlock)
    CfUtils.SetActive(btnNodeGo.transform:Find("StatusHasGet"), isUnlock)
    CfUtils.SetUISwitchImage(btnNodeGo.transform:Find("StatusNotSelect/ImgNotSelect"), isUnlock and 2 or 1)

    if isUnlock then
        CfUtils.FillImage(btnNodeGo.transform:Find("StatusHasGet/ImgIcon"), vo.photoId)
        CfUtils.FillImage(btnNodeGo.transform:Find("StatusHasGet/ImgIcon2"), vo.photoId)

        local isMaxLevel = comp:IsBuffMaxLevel(buffId)
        if isMaxLevel then
            CfUtils.FillText(btnNodeGo.transform:Find("StatusHasGet/TextLevel"), "MAX")
        else
            CfUtils.FillText(btnNodeGo.transform:Find("StatusHasGet/TextLevel"), "Lv."..comp:GetBuffLevel(buffId))
        end
        CfUtils.SetActive(btnNodeGo.transform:Find("StatusHasGet/StatusEquip"), isEquip)

        local isNew = QuestConfMgr:GetInstance():IsNightCatBuffNew(buffId)
        CfUtils.SetActive(btnNodeGo.transform:Find("StatusHasGet/ImgNew"), isNew)
    end
end

function UINightCatInstanceBuffDisplayDialog:OnBtnSelectAll(selectInd, buffId)
    comp:RemoveRedPointList(buffId)

    self:CancelSelectIcon()
    self._curAllBuffSelectIndex = checkNumber(selectInd) + 1
    ind = checkNumber(self._curAllBuffSelectIndex)
    if ind > 0 then
        go = self.AllBuffList:GetShownItemByItemIndex(checkNumber(self._curAllBuffSelectIndex) - 1)
        if go then
            CfUtils.SetActive(go.transform:Find("BtnNode/StatusSelect"), true)
            CfUtils.SetActive(go.transform:Find("BtnNode/StatusHasGet/ImgNew"), false)
            CfUtils.PlayAnimator(go, "Choose")
        end
    end 

    self:FillBuffInfo(LOCAL_CONSTANTS.SELECT_TYPE.ALL_BUFF)
end

function UINightCatInstanceBuffDisplayDialog:CancelSelectIcon()
    local go
    local index = checkNumber(self._curBuffSelectIndex)
    if index > 0 then
        -- 取消已选择的选项
        go = self.CurrentBuffList:GetShownItemByItemIndex(checkNumber(self._curBuffSelectIndex) - 1)
        if go then
            CfUtils.SetActive(go.transform:Find("BtnNode/StatusSelect"), false)
        end
    end
    index = checkNumber(self._curAllBuffSelectIndex)
    if index > 0 then
        go = self.AllBuffList:GetShownItemByItemIndex(checkNumber(self._curAllBuffSelectIndex) - 1)
        if go then
            CfUtils.SetActive(go.transform:Find("BtnNode/StatusSelect"), false)
        end
    end
end

--已装备的直接卸下
function UINightCatInstanceBuffDisplayDialog:OnBtnSelectEquip(selectIndex, buffId)
    if checkNumber(buffId) == 0 then
        return
    end

    self:CancelSelectIcon()
    self._curBuffSelectIndex = checkNumber(selectIndex)
    index = checkNumber(self._curBuffSelectIndex)
    if index > 0 then
        go = self.CurrentBuffList:GetShownItemByItemIndex(checkNumber(self._curBuffSelectIndex) - 1)
        if go then
            CfUtils.SetActive(go.transform:Find("BtnNode/StatusSelect"), true)
            CfUtils.PlayAnimator(go, "Choose")
        end
    end

    self:FillBuffInfo(LOCAL_CONSTANTS.SELECT_TYPE.EQUIP_BUFF)

    --comp:ActivityNightCatGainChangeReq(buffId, 1, function()
    --    self:FillBuffInfo()
    --    self:RefreshInfo(buffId)
    --end)
end

function UINightCatInstanceBuffDisplayDialog:OnGetListItemByIndex(go)
end

function UINightCatInstanceBuffDisplayDialog:SelectedIndex(type)
    type = checkNumber(type)
    if type == LOCAL_CONSTANTS.SELECT_TYPE.ALL_BUFF then
        return checkNumber(self._curAllBuffSelectIndex)
    elseif type == LOCAL_CONSTANTS.SELECT_TYPE.EQUIP_BUFF then
        return checkNumber(self._curBuffSelectIndex)
    end
    return 0
end

function UINightCatInstanceBuffDisplayDialog:BuffId(type, index)
    type = checkNumber(type)
    index = checkInt(index)
    if type == LOCAL_CONSTANTS.SELECT_TYPE.ALL_BUFF then
        return self._allBuffId[index]
    elseif type == LOCAL_CONSTANTS.SELECT_TYPE.EQUIP_BUFF then
        return self._curEquipBuffIds[index]
    end
    return 0
end

--buff 信息
---@param type UINightCatInstanceBuffDisplayDialog.LOCAL_CONSTANTS.SELECT_TYPE
function UINightCatInstanceBuffDisplayDialog:FillBuffInfo(type)
    if checkNumber(self._curAllBuffSelectIndex) < 1 and checkNumber(self._curBuffSelectIndex) < 1 then
        return
    end
    local selectedIndex = self:SelectedIndex(type)
    local buffId = self:BuffId(type, selectedIndex)
    CfUtils.SetActive(self.RightPanel, true)
    local scr = CfUtils.GetLuaScr(self.RightPanel, UINightCatInstanceBuffInfoNode)
    if scr then
        scr:Refresh(buffId, function(isEquip)
            if isEquip then
                self._targetBuffId = buffId
            else
                self:CancelSelectIcon()
            end
            self:RefreshInfo(buffId, isEquip)
        end)
    end
end

--刷新数据变化的buff
function UINightCatInstanceBuffDisplayDialog:RefreshInfo(buffId, isEquip)
    self:InitData()

    self:FillCurBuff()

    local ind = checkNumber(table.keyof(self._curEquipBuffIds, checkNumber(buffId)))
    if ind > 0 then
        local go = self.CurrentBuffList:GetShownItemByItemIndex(checkNumber(ind) - 1)
        CfUtils.PlayAnimator(go, "Assembly")
    end 

    local ind = table.keyof(self._allBuffId, checkString(buffId))
    if ind > 0 then
        local go = self.AllBuffList:GetShownItemByItemIndex(checkNumber(ind) - 1)
        self:FillBuffItem(go, buffId)
    end 
end

